-- Retour arrière du correctif e-mail (15/11) : remet les définitions d'origine.
create or replace function public.gx_my_client() returns uuid language sql stable security definer set search_path = 'public' as $function$ select c.id from clients c where c.email is not null and lower(c.email) = lower(auth.jwt() ->> 'email') and not c.archived order by c.created_at limit 1 $function$;
create or replace function public.is_client_of(coach uuid) returns boolean language sql stable security definer set search_path = 'public' as $function$ select exists(select 1 from public.clients c where c.coach_id = coach and c.email is not null and lower(c.email) = lower(auth.jwt() ->> 'email')); $function$;
create or replace function public.my_payments() returns jsonb language sql stable security definer set search_path = 'public' as $function$ select jsonb_build_object( 'pays', coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'label',p.label,'due',p.due,'amount',p.amount,'status',p.status,'paid_at',p.paid_at,'method',p.method, 'invoice_no',p.invoice_no,'invoice',p.invoice,'client_name',p.client_name) order by p.due) from biz_payments p join clients c on c.id = p.client_id where lower(c.email) = lower((select auth.jwt()->>'email')) and p.coach_id = c.coach_id), '[]'::jsonb), 'paylink', (select s.data->>'paylink' from biz_settings s join clients c on c.coach_id = s.coach_id where lower(c.email) = lower((select auth.jwt()->>'email')) limit 1)) $function$;
